def h(t,b): return f'<h2><span class="dot"></span> {t}</h2>\n{b}'
def callout(k,t): return f'<div class="callout {k}">{t}</div>'
def ul(items): return '<ul>'+''.join(f'<li>{i}</li>' for i in items)+'</ul>'
def ol(items): return '<ol>'+''.join(f'<li>{i}</li>' for i in items)+'</ol>'
def quiz(qs):
    out='<div class="quiz-box">\n'
    for n,(q,opts) in enumerate(qs,1):
        out+=f'<div class="quiz-q">\n<p class="qtext">{n}. {q}</p>\n<div class="opts">\n'
        for t,c in opts: out+=f'<label data-correct="{str(c).lower()}"><input name="q{n}" type="radio"/>{t}</label>\n'
        out+='</div>\n</div>\n'
    return out+'<p class="quiz-result"></p>\n</div>'
def faq(items): return ''.join(f'<details class="faq-item">\n<summary>{q}</summary>\n<p>{a}</p>\n</details>\n' for q,a in items)
